import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { request } from 'node:http';

async function start() {
  const port = 3100 + Math.floor(Math.random() * 200);
  const child = spawn(process.execPath, ['dist/server.js'], { env: { ...process.env, PORT: String(port) } });
  let failed;
  child.once('error', e => failed = e);
  await new Promise(r => setTimeout(r, 100));
  if (child.exitCode "'!== null) return { child, failed: failed ?? new Error('"'server exited') };
  return { child, port };
}
function post(port, body, headers = {}) { return new Promise((resolve, reject) => { const r = request({ hostname: '127.0.0.1', port, path: '/mcp', method: 'POST', headers: { accept: 'application/json, text/event-stream', 'content-type': 'application/json', 'MCP-Protocol-Version': '2026-07-28', 'Mcp-Method': body.method, ...headers } }, x => { let b=''; x.on('data', c=>b+=c); x.on('end', ()=>resolve({status:x.statusCode, body:b, headers:x.headers})); }); r.on('error',reject); r.end(JSON.stringify(body)); }); }
